CREATE TABLE whatsapp_conversations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, account_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, stage VARCHAR(32) NOT NULL DEFAULT 'new', owner_mode VARCHAR(8) NOT NULL DEFAULT 'ai', handoff_reason VARCHAR(200) NULL, last_customer_at DATETIME(6) NULL, last_message_at DATETIME(6) NULL, unread INT NOT NULL DEFAULT 0, offer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, offer_version INT NULL, captured JSON NOT NULL, quote JSON NULL, order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, lock_token VARCHAR(64) NULL, locked_until DATETIME(6) NULL, ai_tokens INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_conversations_pair_uq (account_id,contact_id), UNIQUE KEY whatsapp_conversations_owner_uq (id,user_id), KEY whatsapp_conversations_inbox_idx (user_id,last_message_at,id), CONSTRAINT whatsapp_conversations_owner_ck CHECK (owner_mode IN ('ai','human')), CONSTRAINT whatsapp_conversations_account_fk FOREIGN KEY (account_id,user_id) REFERENCES whatsapp_accounts(id,user_id) ON DELETE CASCADE, CONSTRAINT whatsapp_conversations_contact_fk FOREIGN KEY (contact_id,user_id) REFERENCES whatsapp_contacts(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci